//! Tests for src/woff (run through src/test_woff.zig: `zig test src/test_woff.zig`).
//! Test data is generated by bench/probe/woff/gen_brotli_vectors.mjs and make_testdata.mjs.
const std = @import("std");
const testing = std.testing;
const brotli = @import("brotli.zig");
const woff = @import("woff.zig");
const inflate = @import("../codec/inflate.zig");
const ttf = @import("../font/ttf.zig");

const geist_woff2 = @embedFile("testdata/geist.woff2");
const geist_woff = @embedFile("testdata/geist.woff");
const geist_ttf = @embedFile("testdata/geist.ttf");
const eb_woff2 = @embedFile("testdata/ebgaramond.woff2");
const coll_woff2 = @embedFile("testdata/collection.woff2");
const coll_ref = @embedFile("testdata/collection_ref.ttc");
const bomb = @embedFile("testdata/bomb.br");

fn rd16(b: []const u8, o: usize) u16 {
    return std.mem.readInt(u16, b[o..][0..2], .big);
}
fn rd32(b: []const u8, o: usize) u32 {
    return std.mem.readInt(u32, b[o..][0..4], .big);
}

// ------------------------------------------------------------------ brotli

test "brotli: embedded dictionary decodes without dictionary references (RFC CRC-32)" {
    const d = try brotli.loadDictionaryForTest(testing.allocator);
    defer testing.allocator.free(d);
    try testing.expectEqual(@as(usize, 122784), d.len);
    try testing.expectEqual(@as(u32, 0x5136cb04), std.hash.Crc32.hash(d));
}

test "brotli: Node encoder vectors (q0..11, lgwin 10..24, modes, npostfix/ndirect, dictionary)" {
    const a = testing.allocator;
    const all = try inflate.inflateAlloc(a, @embedFile("testdata/brotli_vectors.bin.deflate"), 64 << 20);
    defer a.free(all);
    var p: usize = 0;
    var n: usize = 0;
    while (p + 8 <= all.len) {
        const rl = std.mem.readInt(u32, all[p..][0..4], .little);
        const cl = std.mem.readInt(u32, all[p + 4 ..][0..4], .little);
        const raw = all[p + 8 ..][0..rl];
        const comp = all[p + 8 + rl ..][0..cl];
        p += 8 + rl + cl;
        const got = try brotli.decompressAlloc(a, comp, rl + 16);
        defer a.free(got);
        try testing.expectEqualSlices(u8, raw, got);
        const buf = try a.alloc(u8, rl);
        defer a.free(buf);
        try testing.expectEqual(rl, try brotli.decompressInto(a, comp, buf));
        if (rl > 0) try testing.expectError(error.OutputTooLarge, brotli.decompressInto(a, comp, buf[0 .. rl - 1]));
        n += 1;
    }
    try testing.expect(n > 50);
}

test "brotli: hand-made streams (empty, uncompressed, metadata, invalid headers)" {
    const a = testing.allocator;
    // RFC 7932 11.1 trivial compressor shapes.
    {
        const r = try brotli.decompressAlloc(a, &.{6}, 10);
        defer a.free(r);
        try testing.expectEqual(@as(usize, 0), r.len);
    }
    const trivial = blk: {
        // c = [12], then per <=65536 chunk: (r&31)<<3, r>>5, 8+(r>>13), bytes; then [3].
        var buf: [16]u8 = undefined;
        const msg = "hello";
        const r: u32 = msg.len - 1;
        buf[0] = 12;
        buf[1] = @intCast((r & 31) << 3);
        buf[2] = @intCast(r >> 5);
        buf[3] = @intCast(8 + (r >> 13));
        @memcpy(buf[4..9], msg);
        buf[9] = 3;
        break :blk buf[0..10].*;
    };
    {
        const r = try brotli.decompressAlloc(a, &trivial, 100);
        defer a.free(r);
        try testing.expectEqualStrings("hello", r);
    }
    {
        // WBITS=16, metadata block skipping "xyz", uncompressed block "hello", ISLAST+ISLASTEMPTY.
        const s = [_]u8{ 0x2C, 0x01, 'x', 'y', 'z', 0x20, 0x00, 0x08, 'h', 'e', 'l', 'l', 'o', 0x03 };
        const r = try brotli.decompressAlloc(a, &s, 100);
        defer a.free(r);
        try testing.expectEqualStrings("hello", r);
        // Non-zero padding before the metadata bytes is rejected.
        var bad = s;
        bad[1] |= 0x80;
        try testing.expectError(error.InvalidData, brotli.decompressAlloc(a, &bad, 100));
        // Metadata length running past the end of the input.
        try testing.expectError(error.InvalidData, brotli.decompressAlloc(a, s[0..4], 100));
    }
    // Truncated: missing final meta-block header.
    try testing.expectError(error.InvalidData, brotli.decompressAlloc(a, trivial[0..9], 100));
    // Large-window marker (WBITS bit pattern 0010001) is rejected.
    try testing.expectError(error.InvalidData, brotli.decompressAlloc(a, &.{ 0x11, 0x01 }, 100));
    try testing.expectError(error.InvalidData, brotli.decompressAlloc(a, &.{}, 100));
}

test "brotli: bomb is stopped by the output cap" {
    const a = testing.allocator;
    try testing.expectError(error.OutputTooLarge, brotli.decompressAlloc(a, bomb, 1 << 20));
    var small: [4096]u8 = undefined;
    try testing.expectError(error.OutputTooLarge, brotli.decompressInto(a, bomb, &small));
}

// ------------------------------------------------------------------ sniff / decode

test "sniff" {
    try testing.expectEqual(woff.Kind.woff2, woff.sniff(geist_woff2));
    try testing.expectEqual(woff.Kind.woff, woff.sniff(geist_woff));
    try testing.expectEqual(woff.Kind.sfnt, woff.sniff(geist_ttf));
    try testing.expectEqual(woff.Kind.sfnt, woff.sniff(coll_ref));
    try testing.expectEqual(woff.Kind.sfnt, woff.sniff("OTTO...."));
    try testing.expectEqual(woff.Kind.unknown, woff.sniff("GIF89a"));
    try testing.expectEqual(woff.Kind.unknown, woff.sniff("wO"));
    try testing.expectError(error.UnsupportedFormat, woff.decode(testing.allocator, geist_ttf));
    try testing.expectError(error.InvalidData, woff.decode(testing.allocator, "wOF2"));
    try testing.expectError(error.InvalidData, woff.decode(testing.allocator, "wOFF"));
}

fn expectFontWorks(data: []const u8, face: u32) !void {
    const f = try ttf.Font.init(data, face);
    var gid: u16 = 0;
    for ([_]u21{ 'A', 0x4E00, 0x9AA8, 0x76F4, 0x5203, 0x4E0E }) |cp| {
        gid = f.glyphIndex(cp);
        if (gid != 0) break;
    }
    try testing.expect(gid != 0);
    const Sink = struct {
        n: u32 = 0,
        pub fn moveTo(s: *@This(), x: f32, y: f32) void {
            _ = .{ x, y };
            s.n += 1;
        }
        pub fn lineTo(s: *@This(), x: f32, y: f32) void {
            _ = .{ x, y };
            s.n += 1;
        }
        pub fn quadTo(s: *@This(), a: f32, b: f32, x: f32, y: f32) void {
            _ = .{ a, b, x, y };
            s.n += 1;
        }
        pub fn cubicTo(s: *@This(), a: f32, b: f32, c: f32, d: f32, x: f32, y: f32) void {
            _ = .{ a, b, c, d, x, y };
            s.n += 1;
        }
        pub fn close(s: *@This()) void {
            s.n += 1;
        }
    };
    var sink: Sink = .{};
    try testing.expect(f.outline(gid, &sink));
    try testing.expect(sink.n > 3);
}

/// Checks the sfnt directory: checksums of every table and head.checkSumAdjustment.
fn expectChecksumsValid(out: []const u8, dir: usize) !void {
    const n = rd16(out, dir + 4);
    var sum: u32 = 0;
    var adj: u32 = 0;
    for (0..n) |i| {
        const p = dir + 12 + 16 * i;
        const off = rd32(out, p + 8);
        const len = rd32(out, p + 12);
        try testing.expect(off % 4 == 0);
        const padded = (len + 3) & ~@as(u32, 3);
        var s: u32 = 0;
        var k: u32 = 0;
        while (k < padded) : (k += 4) s +%= rd32(out, off + k);
        if (rd32(out, p) == 0x68656164) { // head: checksum excludes checkSumAdjustment
            adj = rd32(out, off + 8);
            s -%= adj;
        }
        try testing.expectEqual(rd32(out, p + 4), s);
        sum +%= s;
    }
    var k: usize = 0;
    while (k < 12 + 16 * @as(usize, n)) : (k += 4) sum +%= rd32(out, dir + k);
    try testing.expectEqual(@as(u32, 0xB1B0AFBA) -% sum, adj);
}

test "woff2: geist decodes to the original TrueType file byte for byte" {
    const out = try woff.decode(testing.allocator, geist_woff2);
    defer testing.allocator.free(out);
    try testing.expectEqualSlices(u8, geist_ttf, out);
    try expectChecksumsValid(out, 0);
    try expectFontWorks(out, 0);
}

test "woff1: geist decodes to the original TrueType file byte for byte" {
    const out = try woff.decode(testing.allocator, geist_woff);
    defer testing.allocator.free(out);
    try testing.expectEqualSlices(u8, geist_ttf, out);
    try expectChecksumsValid(out, 0);
}

test "woff2: collection -> TTC identical to the reference decoder; every face loads" {
    const out = try woff.decode(testing.allocator, coll_woff2);
    defer testing.allocator.free(out);
    try testing.expectEqualSlices(u8, coll_ref, out);
    try testing.expectEqual(@as(u32, 3), rd32(out, 8));
    for (0..3) |i| try expectFontWorks(out, @intCast(i));
    // Fonts 0 and 2 share all tables.
    const d0 = rd32(out, 12);
    const d2 = rd32(out, 20);
    try testing.expectEqualSlices(u8, out[d0 + 12 ..][0 .. 16 * @as(usize, rd16(out, d0 + 4))], out[d2 + 12 ..][0 .. 16 * @as(usize, rd16(out, d2 + 4))]);
}

test "woff2: overlapSimpleBitmap restores OVERLAP_SIMPLE on the first flag" {
    const out = try woff.decode(testing.allocator, eb_woff2);
    defer testing.allocator.free(out);
    try expectChecksumsValid(out, 0);
    try expectFontWorks(out, 0);
    const f = try ttf.Font.init(out, 0);
    var with_overlap: u32 = 0;
    var simple: u32 = 0;
    for (0..f.numGlyphs()) |gid| {
        const g = f.glyphData(@intCast(gid));
        if (g.len < 12) continue;
        const nc = std.mem.readInt(i16, g[0..2], .big);
        if (nc <= 0) continue;
        simple += 1;
        const ilen = rd16(g, 10 + 2 * @as(usize, @intCast(nc)));
        const flag0 = g[12 + 2 * @as(usize, @intCast(nc)) + ilen];
        if (flag0 & 0x40 != 0) with_overlap += 1;
    }
    try testing.expect(simple > 300);
    try testing.expectEqual(@as(u32, 365), with_overlap);
}

// ------------------------------------------------------------------ hostile input

test "woff2: header and directory validation" {
    const a = testing.allocator;
    {
        // totalSfntSize much smaller than the real output -> output cap
        var eb: [eb_woff2.len]u8 = eb_woff2.*;
        std.mem.writeInt(u32, eb[16..20], 100, .big);
        try testing.expectError(error.OutputTooLarge, woff.decode(a, &eb));
    }
    var buf: [geist_woff2.len]u8 = geist_woff2.*;
    // numTables = 0
    buf[12] = 0;
    buf[13] = 0;
    try testing.expectError(error.InvalidData, woff.decode(a, &buf));
    buf = geist_woff2.*;
    // totalCompressedSize beyond the file
    std.mem.writeInt(u32, buf[20..24], 0x7fff_ffff, .big);
    try testing.expectError(error.InvalidData, woff.decode(a, &buf));
    buf = geist_woff2.*;
    // first directory entry: unknown transform version on a plain table
    buf[48] |= 0x40;
    try testing.expectError(error.InvalidData, woff.decode(a, &buf));
}

/// Deterministic mutation fuzzing: random byte edits, truncations and length-field damage.
/// In this (safe) build any out-of-bounds access, overflow or leak fails the test.
fn fuzz(seed: u64, src: []const u8, iters: usize, comptime is_brotli: bool) !void {
    var prng = std.Random.DefaultPrng.init(seed);
    const rnd = prng.random();
    const a = testing.allocator;
    const buf = try a.alloc(u8, src.len);
    defer a.free(buf);
    for (0..iters) |it| {
        @memcpy(buf, src);
        var len = src.len;
        const mode = it % 4;
        if (mode == 0 or mode == 3) {
            const edits = 1 + rnd.uintLessThan(usize, 8);
            for (0..edits) |_| {
                // Bias towards the headers/directories where the structure lives.
                const pos = if (rnd.boolean()) rnd.uintLessThan(usize, @min(len, 400)) else rnd.uintLessThan(usize, len);
                buf[pos] = rnd.int(u8);
            }
        }
        if (mode == 1 or mode == 3) len = rnd.uintLessThan(usize, len);
        if (mode == 2) {
            const pos = rnd.uintLessThan(usize, len);
            buf[pos] ^= @as(u8, 1) << rnd.int(u3);
        }
        if (is_brotli) {
            if (brotli.decompressAlloc(a, buf[0..len], 4 << 20)) |r| a.free(r) else |_| {}
        } else {
            if (woff.decode(a, buf[0..len])) |r| {
                try testing.expect(r.len <= woff.max_output);
                a.free(r);
            } else |_| {}
        }
    }
}

test "fuzz: mutated / truncated WOFF2, WOFF, TTC-WOFF2 and brotli inputs never crash" {
    try fuzz(1, geist_woff2, 300, false);
    try fuzz(2, geist_woff, 300, false);
    try fuzz(3, coll_woff2, 200, false);
    try fuzz(4, eb_woff2, 100, false);
    try fuzz(5, bomb, 300, true);
    // The embedded dictionary blob is a large q11 stream with many meta-block features.
    try fuzz(6, @embedFile("brotli_dict.br")[0..4096], 300, true);
}

test "fuzz: every truncation of a small WOFF2 and WOFF fails cleanly" {
    const a = testing.allocator;
    var len: usize = 0;
    while (len < geist_woff2.len) : (len += 97) {
        try testing.expect(std.meta.isError(woff.decode(a, geist_woff2[0..len])));
    }
    len = 0;
    while (len < geist_woff.len) : (len += 89) {
        try testing.expect(std.meta.isError(woff.decode(a, geist_woff[0..len])));
    }
}
